-- ---------------------------------------------------------------------
-- Book Issues (500) + Fine Payments
-- Historical returned loans are written as INSERT (status='issued')
-- immediately followed by an UPDATE to status='returned', mirroring
-- exactly what sp_issue_book + sp_return_book would produce -- so
-- available_copies is maintained purely by the existing triggers,
-- with zero drift and no reconciliation step required.
-- ---------------------------------------------------------------------
INSERT INTO book_issues (book_id, student_id, issue_date, due_date, issued_by, status) VALUES (17, 77, '2025-09-29', '2025-10-06', 2, 'issued');
